<script setup lang="ts">
import {onMounted,ref} from 'vue'
import request,{unwrapResponse} from '@/api/request'
import {getProcessRouteDetail,type ProcessRouteVO} from '@/api/modules/process'
import ProcessGraphView from './ProcessGraphView.vue'
import ProjectProcessRoutePanel from '@/views/project/components/ProjectProcessRoutePanel.vue'
const emit=defineEmits<{history:[]}>()
interface SourceRecord {objectId:number;sourceCode:string;source:Record<string,unknown>}
const source=ref<{routes:SourceRecord[];operations:SourceRecord[]}>({routes:[],operations:[]}),tab=ref<'routes'|'operations'>('routes'),loading=ref(false),error=ref(''),detail=ref<ProcessRouteVO>(),visible=ref(false),editing=ref(false)
async function load(){loading.value=true;error.value='';try{source.value=unwrapResponse(await request.get('/process-routes/current'))}catch(e){error.value=e instanceof Error?e.message:'来源路线读取失败'}finally{loading.value=false}}
async function open(row:SourceRecord){try{detail.value=await getProcessRouteDetail(row.objectId);visible.value=true}catch(e){error.value=e instanceof Error?e.message:'工艺图读取失败'}}
onMounted(load)
</script>
<template><section class="current-process" v-loading="loading"><header><strong>本期 MES 工艺资料</strong><span>{{source.routes.length}} 路线 · {{source.operations.length}} 工序</span><div><el-button size="small" @click="emit('history')">历史／原维护入口</el-button><el-button size="small" @click="load">刷新</el-button></div></header><el-radio-group v-model="tab" size="small"><el-radio-button value="routes">工艺路线</el-radio-button><el-radio-button value="operations">工序定义</el-radio-button></el-radio-group><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="source-scroll"><article v-for="row in source[tab]" :key="row.objectId"><div><strong>{{row.sourceCode}}</strong><small>{{tab==='routes'?row.source.route_name:row.source.operation_name}}</small><small v-if="tab==='operations'">{{row.source.operation_name_es}}</small></div><div><span>{{row.source.product_code||row.source.category}}</span><small>来源版本 {{row.source.version}} · {{row.source.status}}</small><small>来源生效不等同 PLM 工程确认</small></div><el-button v-if="tab==='routes'" size="small" @click="open(row)">节点、依赖与版本</el-button><details v-else><summary>原字段（只读）</summary><pre>{{JSON.stringify(row.source,null,2)}}</pre></details></article></div><el-drawer v-model="visible" :title="detail?.processName||'工艺路线'" size="min(930px,96vw)" destroy-on-close><template v-if="detail"><p>{{detail.sourceRouteCode||detail.processCode}} · {{detail.versionNo}}</p><el-button size="small" @click="editing=true">原工艺维护／复制新版本</el-button><ProcessGraphView v-if="detail.graph" :graph="detail.graph"/></template></el-drawer><el-drawer v-model="editing" title="工艺版本维护" size="min(1040px,98vw)" destroy-on-close append-to-body><ProjectProcessRoutePanel v-if="detail" :project-id="detail.productId" :initial-process-id="detail.processId"/></el-drawer></section></template>
<style scoped>.current-process{height:100%;min-height:0;display:flex;flex-direction:column;gap:8px;container-type:inline-size}.current-process header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.current-process header>div{margin-left:auto}.current-process header span,.current-process small{font-size:12px;color:var(--el-text-color-secondary)}.source-scroll{flex:1;min-height:0;overflow:auto}.source-scroll article{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr) auto;gap:12px;padding:10px 4px;border-bottom:1px solid var(--el-border-color-lighter);align-items:start}.source-scroll article>div{min-width:0;overflow-wrap:anywhere}.source-scroll small{display:block}.source-scroll pre{white-space:pre-wrap;overflow-wrap:anywhere}.source-scroll details{min-width:0}@container(max-width:650px){.source-scroll article{grid-template-columns:1fr}.current-process header>div{margin:0}}</style>
